<?php
class NtcrLicenseClient
{
    const PRODUCT='ntcreatorrewards'; const CFG='NTCR_LICENSE_STATE';
    public function status(){ $s=$this->load();if(empty($s['token']))return array('active'=>false,'message'=>'Lisans etkinleştirilmedi.');$p=$this->payload($s['token'],$s['public_key']);if(!$p)return array('active'=>false,'message'=>'Lisans imzası doğrulanamadı.');if(($p['product_code']??'')!==self::PRODUCT)return array('active'=>false,'message'=>'Lisans bu ürüne ait değil.');if(!in_array($this->domain(),(array)($p['domains']??array()),true))return array('active'=>false,'message'=>'Bu alan adı lisansa bağlı değil.');if(!empty($p['expires_at'])&&strtotime($p['expires_at'])<time())return array('active'=>false,'message'=>'Lisans süresi dolmuş.');return array('active'=>true,'message'=>'Lisans etkin.','payload'=>$p);}
    public function activate($key){$key=strtoupper(trim($key));if(!preg_match('/^NT-[A-Z0-9]{2,8}(?:-[A-Z0-9]{4}){3}$/D',$key))throw new RuntimeException('Geçerli NetwoTürk lisans anahtarı girin.');$pub=$this->call('publickey',array());$r=$this->call('validate',array('product_code'=>self::PRODUCT,'license_key'=>$key,'domain'=>$this->domain(),'usage_json'=>json_encode(array('module_version'=>'1.0.0','ps_version'=>_PS_VERSION_,'php_version'=>PHP_VERSION))));if(empty($r['token'])||empty($pub['public_key'])||!$this->payload($r['token'],$pub['public_key']))throw new RuntimeException(isset($r['error'])?$r['error']:'Lisans doğrulanamadı.');$this->save(array('token'=>$r['token'],'public_key'=>$pub['public_key'],'checked_at'=>date(DATE_ATOM)));return true;}
    private function call($action,$data){$base=rtrim(Configuration::get('NTCR_LICENSE_API'),'/').'/';$url=$base.$action;if(parse_url($url,PHP_URL_SCHEME)!=='https')throw new RuntimeException('Lisans merkezi HTTPS olmalıdır.');$ch=curl_init($url);curl_setopt_array($ch,array(CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($data),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true));$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);if($raw===false||$code<200||$code>=300)throw new RuntimeException('Lisans merkezi bağlantısı başarısız: '.($err?:$code));$json=json_decode($raw,true);if(!is_array($json))throw new RuntimeException('Lisans merkezi geçersiz yanıt verdi.');return $json;}
    private function payload($token,$public){$p=explode('.',$token);if(count($p)!==3)return null;$sig=$this->b64($p[2]);$key=openssl_pkey_get_public($public);if(!$key||openssl_verify($p[0].'.'.$p[1],$sig,$key,OPENSSL_ALGO_SHA256)!==1)return null;$j=json_decode($this->b64($p[1]),true);return is_array($j)?$j:null;}
    private function b64($s){$s=strtr($s,'-_','+/');return base64_decode($s.str_repeat('=',(4-strlen($s)%4)%4),true);}
    private function domain(){return strtolower(preg_replace('/:\d+$/','',(string)Tools::getHttpHost(false)));}
    private function load(){ $raw=Configuration::get(self::CFG);if(!$raw)return array();$j=json_decode($raw,true);return is_array($j)?$j:array(); }
    private function save($s){Configuration::updateValue(self::CFG,json_encode($s),false);}
}
